 * Recursive-descent parser for formula bodies. Produces an AST, or `null`
 * when the text is not accepted by the grammar.
 *
 * Precedence, loosest first: comparisons, then + -, then * /, then ^
 * (right-assoc), then a leading unary + or - (binds tighter than ^).
 *
 * A range (`A1:B3`) is only accepted directly as a function-call argument.
 */

import { tokenize } from './lexer.js'

const FAIL = Symbol('fail')

class TokenStream {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }
  peek() {
    return this.tokens[this.pos]
  }
  next() {
    return this.tokens[this.pos++]
  }
}

const COMPARISON_OPS = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])

function parseComparison(ts) {
  let left = parseAdditive(ts)
  if (left === FAIL) return FAIL
  while (COMPARISON_OPS.has(ts.peek().type)) {
    const op = ts.next().type
    const right = parseAdditive(ts)
    if (right === FAIL) return FAIL
    left = { type: 'binary', op, left, right }
  }
  return left
}

function parseAdditive(ts) {
  let left = parseMultiplicative(ts)
  if (left === FAIL) return FAIL
  while (ts.peek().type === 'PLUS' || ts.peek().type === 'MINUS') {
    const op = ts.next().type
    const right = parseMultiplicative(ts)
    if (right === FAIL) return FAIL
    left = { type: 'binary', op, left, right }
  }
  return left
}

function parseMultiplicative(ts) {
  let left = parsePower(ts)
  if (left === FAIL) return FAIL
  while (ts.peek().type === 'STAR' || ts.peek().type === 'SLASH') {
    const op = ts.next().type
    const right = parsePower(ts)
    if (right === FAIL) return FAIL
    left = { type: 'binary', op, left, right }
  }
  return left
}

function parsePower(ts) {
  const base = parseUnary(ts)
  if (base === FAIL) return FAIL
  if (ts.peek().type === 'CARET') {
    ts.next()
    const right = parsePower(ts)
    if (right === FAIL) return FAIL
    return { type: 'binary', op: 'CARET', left: base, right }
  }
  return base
}

function parseUnary(ts) {
  const t = ts.peek()
  if (t.type === 'PLUS' || t.type === 'MINUS') {
    ts.next()
    const expr = parseUnary(ts)
    if (expr === FAIL) return FAIL
    return { type: 'unary', op: t.type, expr }
  }
  return parsePrimary(ts)
}

const FUNCTION_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

function parsePrimary(ts) {
  const t = ts.peek()

  if (t.type === 'NUMBER') {
    ts.next()
    return { type: 'num', value: parseFloat(t.value) }
  }

  if (t.type === 'LPAREN') {
    ts.next()
    const e = parseComparison(ts)
    if (e === FAIL) return FAIL
    if (ts.peek().type !== 'RPAREN') return FAIL
    ts.next()
    return e
  }

  if (t.type === 'WORD') {
    ts.next()
    const upper = t.value.toUpperCase()
    if (upper === 'TRUE') return { type: 'bool', value: true }
    if (upper === 'FALSE') return { type: 'bool', value: false }

    if (ts.peek().type === 'LPAREN') {
      ts.next()
      const args = []
      if (ts.peek().type !== 'RPAREN') {
        while (true) {
          const arg = parseArgument(ts)
          if (arg === FAIL) return FAIL
          args.push(arg)
          if (ts.peek().type === 'COMMA') {
            ts.next()
            continue
          }
          break
        }
      }
      if (ts.peek().type !== 'RPAREN') return FAIL
      ts.next()
      return { type: 'call', name: upper, args }
    }

    return { type: 'addr', address: upper }
  }

  return FAIL
}

function parseArgument(ts) {
  const t = ts.peek()
  if (t.type === 'WORD') {
    const save = ts.pos
    ts.next()
    const startWord = t.value.toUpperCase()
    if (ts.peek().type === 'COLON') {
      ts.next()
      const t2 = ts.peek()
      if (t2.type === 'WORD') {
        ts.next()
        const endWord = t2.value.toUpperCase()
        return { type: 'range', start: startWord, end: endWord }
      }
      return FAIL
    }
    ts.pos = save
  }
  return parseComparison(ts)
}

