  const tokens = tokenize(text)
  const ts = new TokenStream(tokens)
  const ast = parseComparison(ts)
  if (ast === FAIL) return null
  if (ts.peek().type !== 'EOF') return null
  return ast
}

export { FUNCTION_NAMES }
"}

