 * Evaluates every declared cell of a sheet to a value, with formula
 * parsing, cycle detection, and memoization.
 */

import { parseFormula } from './parser.js'
import { parseAddress, expandRange } from './address.js'
import { num, text, bool, err, isError, toNumber, ERROR_TOKENS } from './values.js'

function parseLiteral(content) {
  if (content === '') return num(0)
  if (/^-?\d+(\.\d+)?$/.test(content)) return num(parseFloat(content))
  if (ERROR_TOKENS.includes(content)) return err(content)
  return text(content)
}

const COMPARISON_OPS = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])

function rankKind(k) {
  return k === 'number' ? 0 : k === 'text' ? 1 : 2
}

function compareValues(l, r) {
  if (l.kind === r.kind) {
    if (l.kind === 'number') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
    if (l.kind === 'text') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
    // boolean: false below true
    if (l.value === r.value) return 0
    return l.value ? 1 : -1
  }
  const d = rankKind(l.kind) - rankKind(r.kind)
  return d < 0 ? -1 : d > 0 ? 1 : 0
}

function evalComparison(op, l, r) {
  if (isError(l)) return l
  if (isError(r)) return r
  const cmp = compareValues(l, r)
  switch (op) {
    case 'EQ': return bool(cmp === 0)
    case 'NE': return bool(cmp !== 0)
    case 'LT': return bool(cmp < 0)
    case 'LE': return bool(cmp <= 0)
    case 'GT': return bool(cmp > 0)
    case 'GE': return bool(cmp >= 0)
  }
}

function evalBinaryArith(op, l, r) {
  if (isError(l)) return l
  if (isError(r)) return r
  const ln = toNumber(l)
  if (isError(ln)) return ln
  const rn = toNumber(r)
  if (isError(rn)) return rn
  let res
  switch (op) {
    case 'PLUS': res = ln.value + rn.value; break
    case 'MINUS': res = ln.value - rn.value; break
    case 'STAR': res = ln.value * rn.value; break
    case 'SLASH':
      if (rn.value === 0) return err('#DIV/0!')
      res = ln.value / rn.value
      break
    case 'CARET': res = Math.pow(ln.value, rn.value); break
  }
  if (!Number.isFinite(res)) return err('#DIV/0!')
  return num(res)
}

function evalUnary(op, v) {
  if (isError(v)) return v
  const n = toNumber(v)
  if (isError(n)) return n
  const res = op === 'MINUS' ? -n.value : n.value
  if (!Number.isFinite(res)) return err('#DIV/0!')
  return num(res)
}

const AGG_FUNCS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

function numResult(x) {
  if (!Number.isFinite(x)) return err('#DIV/0!')
  return num(x)
}

class EvalState {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map() // address -> Value
    this.visiting = new Set()
    this.formulaCache = new Map() // address -> ast|null
  }
}

