  if (state.cache.has(address)) return state.cache.get(address)
  if (state.visiting.has(address)) return err('#CYCLE!')

  const content = state.cells.get(address)
  if (content === undefined) {
    const v = num(0)
    state.cache.set(address, v)
    return v
