  if (argNode.type === 'range') {
    const addrs = expandRange(argNode.start, argNode.end)
    if (addrs === null) return [err('#REF!')]
    return addrs.map((a) => getCellValue(state, a))
  }
  return [evalNode(state, argNode)]
}

function evalCall(state, node) {
  const name = node.name

  if (name === 'IF') {
    if (node.args.length !== 3) return err('#ERR!')
    const [condNode, thenNode, elseNode] = node.args
    if (condNode.type === 'range') return err('#ERR!')
    const condVal = evalNode(state, condNode)
    if (isError(condVal)) return condVal
    let condBool
    if (condVal.kind === 'boolean') condBool = condVal.value
    else if (condVal.kind === 'number') condBool = condVal.value !== 0
    else return err('#VALUE!')
    const branch = condBool ? thenNode : elseNode
    if (branch.type === 'range') return err('#ERR!')
    return evalNode(state, branch)
  }

