    for (const v of values) if (isError(v)) return v
    const n = toNumber(values[0])
    if (isError(n)) return n
    return num(Math.abs(n.value))
  }

  if (AGG_FUNCS.has(name)) {
    if (node.args.length < 1) return err('#ERR!')
    const allValues = []
    for (const argNode of node.args) {
      allValues.push(...evalArgValues(state, argNode))
    }
    for (const v of allValues) if (isError(v)) return v

    if (name === 'COUNT') {
      let c = 0
      for (const v of allValues) if (v.kind === 'number') c++
      return num(c)
    }

    const nums = []
    for (const v of allValues) {
      const n = toNumber(v)
      if (isError(n)) return n
      nums.push(n.value)
    }

    if (name === 'SUM') return numResult(nums.reduce((a, b) => a + b, 0))
    if (name === 'MIN') return numResult(Math.min(...nums))
    if (name === 'MAX') return numResult(Math.max(...nums))
