    case 'bool': return bool(node.value)
    case 'addr': {
      const addr = parseAddress(node.address)
      if (!addr) return err('#REF!')
      return getCellValue(state, node.address)
    }
    case 'range':
      return err('#ERR!')
    case 'unary':
      return evalUnary(node.op, evalNode(state, node.expr))
    case 'binary': {
      const l = evalNode(state, node.left)
      const r = evalNode(state, node.right)
      if (COMPARISON_OPS.has(node.op)) return evalComparison(node.op, l, r)
      return evalBinaryArith(node.op, l, r)
    }
    case 'call':
      return evalCall(state, node)
  }
