{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e2-harness-vs-product-sonnet-t5-sealed/cell-0qJ6gp/src/deps.js","content":"/**
 * Computes the direct dependencies of each declared cell: the addresses its
 * content names, ranges expanded, restricted to the addressable range.
 * Purely syntactic - no evaluation, no cycle detection.
 */

import { parseFormula } from './parser.js'
import { parseAddress, expandRange, sortAddresses } from './address.js'

function collectRefs(node, out) {
  switch (node.type) {
    case 'addr':
      if (parseAddress(node.address)) out.add(node.address)
      break
    case 'range': {
      const addrs = expandRange(node.start, node.end)
      if (addrs) for (const a of addrs) out.add(a)
      break
    }
    case 'unary':
      collectRefs(node.expr, out)
      break
    case 'binary':
      collectRefs(node.left, out)
      collectRefs(node.right, out)
      break
    case 'call':
      for (const a of node.args) collectRefs(a, out)
      break
    default:
      break
  }
}

export function computeDeps(cells) {
  const result = new Map()
  for (const [address, content] of cells) {
    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      if (ast) {
        const found = new Set()
        collectRefs(ast, found)
        result.set(address, sortAddresses([...found]))
        continue
      }
    }
    result.set(address, [])
  }
  return result
}
"}

