function codePointCompare(a, b) {
  const ai = Array.from(a, (c) => c.codePointAt(0))
  const bi = Array.from(b, (c) => c.codePointAt(0))
  const len = Math.min(ai.length, bi.length)
  for (let i = 0; i < len; i++) {
    if (ai[i] !== bi[i]) return ai[i] - bi[i]
  }
  return ai.length - bi.length
}

function sortedKeys(map) {
  return [...map.keys()].sort(codePointCompare)
}

function formatFloat(n) {
  let s = JSON.stringify(n)
  if (!s.includes('.') && !s.includes('e') && !s.includes('E')) s += '.0'
  return s
}

export function typeOf(node) {
  switch (node.kind) {
    case 'table': return 'table'
    case 'aot': return 'array'
    case 'array': return 'array'
    case 'string': return 'string'
    case 'integer': return 'integer'
    case 'float': return 'float'
    case 'boolean': return 'boolean'
    default: throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJsonString(node, indent = 0) {
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node.map)
      if (keys.length === 0) return '{}'
      const pad = '  '.repeat(indent + 1)
      const closePad = '  '.repeat(indent)
      const lines = keys.map(
        (k) => `${pad}${JSON.stringify(k)}: ${toJsonString(node.map.get(k), indent + 1)}`
      )
      return `{\n${lines.join(',\n')}\n${closePad}}`
    }
    case 'aot':
    case 'array': {
      const items = node.items
      if (items.length === 0) return '[]'
      const pad = '  '.repeat(indent + 1)
      const closePad = '  '.repeat(indent)
      const lines = items.map((it) => pad + toJsonString(it, indent + 1))
      return `[\n${lines.join(',\n')}\n${closePad}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value.toString()
    case 'float':
      return formatFloat(node.value)
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function collectKeys(node, path, out) {
  if (node.kind === 'table') {
    for (const k of sortedKeys(node.map)) {
      const child = node.map.get(k)
      const p = path === '' ? k : `${path}.${k}`
      out.push(`${p} ${typeOf(child)}`)
      collectKeys(child, p, out)
    }
  } else if (node.kind === 'aot' || node.kind === 'array') {
    node.items.forEach((item, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${typeOf(item)}`)
