content.arguments:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e2-harness-vs-product-sonnet-t5-sealed/cell-3n9S6m/src/policies.js","content":"/**
 * Policy implementations: token bucket and sliding window.
 * Each keeps one independent state per key.
 */

export class Bucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  advance(key, tick) {
    let st = this.states.get(key)
    if (!st) {
      st = { numer: this.capacity * this.per, lastTick: tick }
      this.states.set(key, st)
      return
    }
    const delta = tick - st.lastTick
    if (delta > 0n) {
      st.numer += this.refill * delta
      const max = this.capacity * this.per
      if (st.numer > max) st.numer = max
      st.lastTick = tick
    }
  }

  allow(key) {
    const st = this.states.get(key)
    return st.numer >= this.per
  }

  record(key) {
    const st = this.states.get(key)
    st.numer -= this.per
  }
}

export class Window {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let st = this.states.get(key)
    if (!st) {
      st = { queue: [] }
      this.states.set(key, st)
    }
    const threshold = tick - this.span
    let i = 0
    while (i < st.queue.length && st.queue[i] <= threshold) i++
    if (i > 0) st.queue.splice(0, i)
  }

  allow(key) {
    const st = this.states.get(key)
    return BigInt(st.queue.length) < this.limit
  }

  record(key, tick) {
    const st = this.states.get(key)
    st.queue.push(tick)
  }
}
"}

