 * Parses a limiter file into policies, routes and events, enforcing every
 * validation rule from the specification and reporting the first failure
 * with its line number.
 */

import { Bucket, Window } from './policies.js'

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function validateName(value, line, label) {
  if (!NAME_RE.test(value)) {
    throw new ParseError(line, `invalid ${label} ${value}`)
  }
}

function validateInt(str, line, field, min) {
  if (!INT_RE.test(str)) {
    throw new ParseError(line, `${field} must be an integer of at least ${min}`)
  }
  const value = BigInt(str)
  if (value < BigInt(min)) {
    throw new ParseError(line, `${field} must be an integer of at least ${min}`)
  }
  return value
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routeList = []
  const routePrefixes = new Set()
  const events = []

  let eventSeen = false
  let lastTick = null
  let lastTickStr = null

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]
    const rest = tokens.slice(1)

    if (directive === 'bucket') {
      if (eventSeen) throw new ParseError(lineNumber, 'declarations must come before the first event')
      if (rest.length !== 4) throw new ParseError(lineNumber, 'expected bucket <name> <capacity> <refill> <per>')
      const [name, capacityStr, refillStr, perStr] = rest
      validateName(name, lineNumber, 'policy name')
      if (policies.has(name)) throw new ParseError(lineNumber, `policy ${name} is declared twice`)
      const capacity = validateInt(capacityStr, lineNumber, 'capacity', 1)
      const refill = validateInt(refillStr, lineNumber, 'refill', 0)
      const per = validateInt(perStr, lineNumber, 'per', 1)
      policies.set(name, new Bucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (eventSeen) throw new ParseError(lineNumber, 'declarations must come before the first event')
      if (rest.length !== 3) throw new ParseError(lineNumber, 'expected window <name> <limit> <span>')
      const [name, limitStr, spanStr] = rest
      validateName(name, lineNumber, 'policy name')
      if (policies.has(name)) throw new ParseError(lineNumber, `policy ${name} is declared twice`)
      const limit = validateInt(limitStr, lineNumber, 'limit', 0)
      const span = validateInt(spanStr, lineNumber, 'span', 1)
      policies.set(name, new Window(limit, span))
    } else if (directive === 'route') {
      if (eventSeen) throw new ParseError(lineNumber, 'declarations must come before the first event')
      if (rest.length < 2) throw new ParseError(lineNumber, 'expected route <prefix> <policy>...')
      const [prefix, ...policyNames] = rest
      validateName(prefix, lineNumber, 'route prefix')
      if (routePrefixes.has(prefix)) throw new ParseError(lineNumber, `prefix ${prefix} is routed twice`)
      const routePolicies = []
      for (const name of policyNames) {
        if (!policies.has(name)) throw new ParseError(lineNumber, `unknown policy ${name}`)
        routePolicies.push({ name, policy: policies.get(name) })
      }
      routePrefixes.add(prefix)
      routeList.push({ prefix, policies: routePolicies })
    } else if (directive === 'event') {
      eventSeen = true
      if (rest.length !== 2) throw new ParseError(lineNumber, 'expected event <tick> <key>')
      const [tickStr, key] = rest
      const tick = validateInt(tickStr, lineNumber, 'tick', 0)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(lineNumber, `tick ${tickStr} is before tick ${lastTickStr}`)
      }
      validateName(key, lineNumber, 'key')
      lastTick = tick
      lastTickStr = tickStr
      events.push({ tick, tickStr, key })
    } else {
      throw new ParseError(lineNumber, `unknown directive ${directive}`)
    }
  }

  routeList.sort((a, b) => b.prefix.length - a.prefix.length)

  return { policies, routes: routeList, events }
}

export function findRoute(routes, key) {
  for (const route of routes) {
    if (key.startsWith(route.prefix)) return route
  }
  return null
}
"}

