{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e2-harness-vs-product-sonnet-t5-sealed/cell-3n9S6m/src/simulate.js","content":"/**
 * Runs the parsed events against the parsed routes/policies and returns a
 * verdict for each event in log order.
 */

import { findRoute } from './parser.js'

export function simulate({ routes, events }) {
  const verdicts = []

  for (const event of events) {
    const { tick, tickStr, key } = event
    const route = findRoute(routes, key)

    if (!route) {
      verdicts.push({ tick, tickStr, key, allow: true, denyPolicy: null })
      continue
    }

    for (const { policy } of route.policies) {
      policy.advance(key, tick)
    }

    let denyName = null
    for (const { name, policy } of route.policies) {
      if (!policy.allow(key)) {
        denyName = name
        break
      }
    }

    if (denyName === null) {
      for (const { policy } of route.policies) {
        policy.record(key, tick)
      }
      verdicts.push({ tick, tickStr, key, allow: true, denyPolicy: null })
    } else {
