// It walks the input one Unicode code point at a time, tracking line and
// column, and produces a flat list of tokens or throws a LexError.

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

// Longest match first.
const PUNCTS2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCTS1 = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

function isLetter(c) {
  return c !== undefined && /[A-Za-z]/.test(c)
}
function isDigit(c) {
  return c !== undefined && /[0-9]/.test(c)
}
function isHexDigit(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}
function isOctDigit(c) {
  return c !== undefined && /[0-7]/.test(c)
}
function isBinDigit(c) {
  return c !== undefined && /[01]/.test(c)
}
function isIdentStart(c) {
  return isLetter(c) || c === '_'
}
function isIdentCont(c) {
  return isLetter(c) || isDigit(c) || c === '_'
}
function isTrailer(c) {
  return isLetter(c) || isDigit(c) || c === '_'
}

export class LexError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

class Scanner {
  constructor(input) {
    this.cp = Array.from(input)
    this.pos = 0
    this.line = 1
    this.col = 1
  }

  peek(k = 0) {
    return this.cp[this.pos + k]
  }

  advance() {
    const c = this.cp[this.pos]
    if (c === undefined) return undefined
    this.pos++
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = Math.floor((this.col - 1) / 4) * 4 + 5
    } else {
      this.col++
    }
    return c
  }

  here() {
    return { line: this.line, col: this.col }
  }

  fail(pos, reason) {
    throw new LexError(pos.line, pos.col, reason)
  }

