  // between two digits of the run. Assumes the current position already
  // sits on a digit; returns the consumed text (including the first digit).
  scanDigitRun(isDigitFn) {
    let text = this.advance() // first digit, guaranteed by caller
    while (true) {
      if (isDigitFn(this.peek())) {
        text += this.advance()
      } else if (this.peek() === '_' && isDigitFn(this.peek(1))) {
        text += this.advance() // underscore
      } else {
        break
      }
    }
    return text
  }

  scanTrailer(text) {
    while (isTrailer(this.peek())) {
      text += this.advance()
    }
    return text
  }

