      text += this.advance() // 0
      text += this.advance() // x/X
      if (isHexDigit(this.peek())) {
        text += this.scanDigitRun(isHexDigit)
      } else {
        text = this.scanTrailer(text)
        this.fail(start, `invalid number ${text}`)
