  scanString() {
    const start = this.here()
    this.advance() // opening quote
    let value = ''
    while (true) {
      const c = this.peek()
      if (c === undefined) this.fail(start, 'unterminated string')
      if (c === '\n') {
        const nlPos = this.here()
        this.fail(nlPos, 'newline in string')
      }
      if (c === '"') { this.advance(); break }
      if (c === '\\') {
        const escPos = this.here()
        this.advance() // backslash
        value += this.readEscape(escPos, start)
        continue
      }
      value += this.advance()
    }
    return { line: start.line, col: start.col, kind: 'string', text: JSON.stringify(value) }
  }

  scanRawString() {
    const start = this.here()
    this.advance() // r
    this.advance() // "
    let value = ''
    while (true) {
      const c = this.peek()
      if (c === undefined) this.fail(start, 'unterminated string')
      if (c === '"') { this.advance(); break }
      value += this.advance()
    }
    return { line: start.line, col: start.col, kind: 'rawstring', text: JSON.stringify(value) }
  }

  skipLineComment() {
    this.advance() // /
    this.advance() // /
    while (this.peek() !== undefined && this.peek() !== '\n') {
      this.advance()
    }
  }

  skipBlockComment() {
    const openPos = this.here()
    this.advance() // /
    this.advance() // *
    let depth = 1
    while (depth > 0) {
      if (this.peek() === undefined) this.fail(openPos, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance(); this.advance()
        depth++
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance(); this.advance()
        depth--
      } else {
        this.advance()
      }
    }
  }

  scanPunct() {
    const start = this.here()
    const two = (this.peek() ?? '') + (this.peek(1) ?? '')
    if (PUNCTS2.includes(two)) {
      this.advance(); this.advance()
      return { line: start.line, col: start.col, kind: 'punct', text: two }
    }
    const one = this.peek()
    if (PUNCTS1.includes(one)) {
      this.advance()
      return { line: start.line, col: start.col, kind: 'punct', text: one }
    }
    this.fail(start, `unexpected character ${one}`)
  }

  nextToken() {
    while (true) {
      const c = this.peek()
      if (c === undefined) return undefined
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        this.skipLineComment()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
        continue
      }
      if (c === '"') return this.scanString()
      if (c === 'r' && this.peek(1) === '"') return this.scanRawString()
      if (isIdentStart(c)) return this.scanIdent()
      if (isDigit(c)) return this.scanNumber()
      return this.scanPunct()
    }
  }
}

export function tokenize(input) {
  const scanner = new Scanner(input)
  const tokens = []
  while (true) {
    const tok = scanner.nextToken()
    if (tok === undefined) break
    tokens.push(tok)
  }
  return tokens
}
