      } else if (this.peek() === '_' && isDigitFn(this.peek(1))) {
        text += this.advance() // underscore
      } else {
        break
      }
    }
    return text
  }

  scanTrailer(text) {
    while (isTrailer(this.peek())) {
      text += this.advance()
    }
    return text
  }

  scanNumber() {
    const start = this.here()
    let text = ''
    if (this.peek() === '0' && (this.peek(1) === 'x' || this.peek(1) === 'X')) {
      text += this.advance() // 0
      text += this.advance() // x/X
      if (isHexDigit(this.peek())) {
        text += this.scanDigitRun(isHexDigit)
      } else {
        text = this.scanTrailer(text)
        this.fail(start, `invalid number ${text}`)
      }
    } else if (this.peek() === '0' && (this.peek(1) === 'b' || this.peek(1) === 'B')) {
      text += this.advance()
      text += this.advance()
      if (isBinDigit(this.peek())) {
        text += this.scanDigitRun(isBinDigit)
      } else {
        text = this.scanTrailer(text)
        this.fail(start, `invalid number ${text}`)
      }
    } else if (this.peek() === '0' && (this.peek(1) === 'o' || this.peek(1) === 'O')) {
      text += this.advance()
      text += this.advance()
      if (isOctDigit(this.peek())) {
        text += this.scanDigitRun(isOctDigit)
      } else {
        text = this.scanTrailer(text)
        this.fail(start, `invalid number ${text}`)
      }
    } else {
      text += this.scanDigitRun(isDigit)
      if (this.peek() === '.' && isDigit(this.peek(1))) {
        text += this.advance() // .
        text += this.scanDigitRun(isDigit)
      }
      if (this.peek() === 'e' || this.peek() === 'E') {
        const hasSign = this.peek(1) === '+' || this.peek(1) === '-'
        const digitAfter = hasSign ? this.peek(2) : this.peek(1)
        if (isDigit(digitAfter)) {
          text += this.advance() // e/E
          if (hasSign) text += this.advance()
          text += this.scanDigitRun(isDigit)
        }
      }
    }

    if (isTrailer(this.peek())) {
      text = this.scanTrailer(text)
      this.fail(start, `invalid number ${text}`)
    }

    return { line: start.line, col: start.col, kind: 'number', text }
  }

  scanIdent() {
    const start = this.here()
    let text = this.advance()
    while (isIdentCont(this.peek())) {
      text += this.advance()
    }
    return { line: start.line, col: start.col, kind: KEYWORDS.has(text) ? 'keyword' : 'ident', text }
  }

  // Reads one escape sequence after a backslash has been consumed.
  // `openPos` is the position of the opening quote, used when the input
  // ends before the escape (or the string) is complete.
  readEscape(escPos, openPos) {
    const c = this.peek()
    if (c === undefined) this.fail(openPos, 'unterminated string')
    if (c === 'n') { this.advance(); return '\n' }
    if (c === 't') { this.advance(); return '\t' }
    if (c === 'r') { this.advance(); return '\r' }
    if (c === '\\') { this.advance(); return '\\' }
    if (c === '"') { this.advance(); return '"' }
    if (c === '0') { this.advance(); return '\0' }
    if (c === 'x') {
      this.advance()
      let digits = ''
      for (let i = 0; i < 2; i++) {
        const d = this.peek()
        if (d === undefined) this.fail(openPos, 'unterminated string')
        if (!isHexDigit(d)) this.fail(escPos, 'invalid escape \\x')
        digits += this.advance()
      }
      return String.fromCharCode(parseInt(digits, 16))
    }
    if (c === 'u') {
      this.advance()
      const brace = this.peek()
      if (brace === undefined) this.fail(openPos, 'unterminated string')
      if (brace !== '{') this.fail(escPos, 'invalid escape \\u')
      this.advance()
      let digits = ''
      while (true) {
        const d = this.peek()
        if (d === undefined) this.fail(openPos, 'unterminated string')
        if (d === '}') { this.advance(); break }
        if (!isHexDigit(d)) this.fail(escPos, 'invalid escape \\u')
        digits += this.advance()
      }
      if (digits.length === 0) this.fail(escPos, 'invalid escape \\u')
      const value = parseInt(digits, 16)
      if (value > 0x10ffff) this.fail(escPos, 'invalid escape \\u')
      return String.fromCodePoint(value)
    }
    this.advance()
    this.fail(escPos, `invalid escape \\${c}`)
  }

  scanString() {
    const start = this.here()
    this.advance() // opening quote
    let value = ''
    while (true) {
      const c = this.peek()
      if (c === undefined) this.fail(start, 'unterminated string')
      if (c === '\n') {
        const nlPos = this.here()
        this.fail(nlPos, 'newline in string')
      }
      if (c === '"') { this.advance(); break }
      if (c === '\\') {
        const escPos = this.here()
        this.advance() // backslash
        value += this.readEscape(escPos, start)
        continue
      }
      value += this.advance()
    }
    return { line: start.line, col: start.col, kind: 'string', text: JSON.stringify(value) }
  }

  scanRawString() {
    const start = this.here()
    this.advance() // r
    this.advance() // "
    let value = ''
    while (true) {
      const c = this.peek()
      if (c === undefined) this.fail(start, 'unterminated string')
      if (c === '"') { this.advance(); break }
      value += this.advance()
    }
    return { line: start.line, col: start.col, kind: 'rawstring', text: JSON.stringify(value) }
  }

  skipLineComment() {
    this.advance() // /
    this.advance() // /
    while (this.peek() !== undefined && this.peek() !== '\n') {
      this.advance()
    }
  }

  skipBlockComment() {
    const openPos = this.here()
    this.advance() // /
    this.advance() // *
    let depth = 1
    while (depth > 0) {
      if (this.peek() === undefined) this.fail(openPos, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance(); this.advance()
        depth++
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance(); this.advance()
        depth--
      } else {
        this.advance()
      }
    }
  }

  scanPunct() {
    const start = this.here()
    const two = (this.peek() ?? '') + (this.peek(1) ?? '')
    if (PUNCTS2.includes(two)) {
      this.advance(); this.advance()
      return { line: start.line, col: start.col, kind: 'punct', text: two }
    }
    const one = this.peek()
    if (PUNCTS1.includes(one)) {
      this.advance()
      return { line: start.line, col: start.col, kind: 'punct', text: one }
    }
    this.fail(start, `unexpected character ${one}`)
  }

  nextToken() {
    while (true) {
      const c = this.peek()
      if (c === undefined) return undefined
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        this.skipLineComment()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        this.skipBlockComment()
        continue
      }
      if (c === '"') return this.scanString()
      if (c === 'r' && this.peek(1) === '"') return this.scanRawString()
      if (isIdentStart(c)) return this.scanIdent()
      if (isDigit(c)) return this.scanNumber()
      return this.scanPunct()
    }
  }
}

export function tokenize(input) {
  const scanner = new Scanner(input)
  const tokens = []
  while (true) {
    const tok = scanner.nextToken()
    if (tok === undefined) break
    tokens.push(tok)
  }
  return tokens
}
"}

