 * Core three-way merge logic: LCS-based diffing of a side against a base,
 * change extraction, region grouping and resolution.
 */

/**
 * Compute the specific LCS alignment between `side` and `base` per the
 * tie-breaking rule: on a mismatch, advance the side whose remaining
 * subsequence (looking forward) is at least as long as the other's,
 * preferring to advance the base on a tie.
 *
 * Returns a list of [sideIndex, baseIndex] pairs of matched (equal) lines,
 * in increasing order.
 */
function computeMatches(side, base) {
  const n = side.length
  const m = base.length
  // dp[i * (m+1) + j] = LCS length of side[i:] and base[j:]
  const dp = new Int32Array((n + 1) * (m + 1))
  const stride = m + 1
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (side[i] === base[j]) {
        dp[i * stride + j] = dp[(i + 1) * stride + (j + 1)] + 1
      } else {
        const advanceSide = dp[(i + 1) * stride + j]
        const advanceBase = dp[i * stride + (j + 1)]
        dp[i * stride + j] = advanceSide > advanceBase ? advanceSide : advanceBase
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (side[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
    } else {
      const advanceBaseValue = dp[i * stride + (j + 1)]
      const advanceSideValue = dp[(i + 1) * stride + j]
      if (advanceBaseValue >= advanceSideValue) {
        j++
      } else {
        i++
      }
    }
  }
  return matches
}

/**
 * Turn matches between `side` and `base` into a list of changes: runs of
 * base lines replaced by runs of side lines, covering every stretch the
 * matched subsequence does not cover.
 */
function computeChanges(side, base, matches, source) {
  const changes = []
  let prevI = 0
  let prevJ = 0
  const pairs = matches.concat([[side.length, base.length]])
  for (const [i, j] of pairs) {
    const sideRun = side.slice(prevI, i)
    const baseStart = prevJ
    const baseEnd = j
    if (sideRun.length > 0 || baseEnd > baseStart) {
      changes.push({ source, baseStart, baseEnd, lines: sideRun })
    }
    prevI = i + 1
    prevJ = j + 1
  }
  return changes
}

/** Group a sorted, merged list of changes into overlapping regions. */
function computeRegions(allChanges) {
  const regions = []
  let idx = 0
  while (idx < allChanges.length) {
    let start = allChanges[idx].baseStart
    let end = allChanges[idx].baseEnd
    const touching = [allChanges[idx]]
    idx++
    while (idx < allChanges.length && allChanges[idx].baseStart <= end) {
      if (allChanges[idx].baseEnd > end) end = allChanges[idx].baseEnd
      touching.push(allChanges[idx])
      idx++
    }
    regions.push({ baseStart: start, baseEnd: end, touching })
  }
  return regions
}

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

/** Build a side's replacement lines for a region from its own changes. */
function sideLinesForRegion(baseDoc, region, changes) {
  if (changes.length === 0) {
    return baseDoc.slice(region.baseStart, region.baseEnd)
  }
  const sorted = changes.slice().sort((a, b) => a.baseStart - b.baseStart)
  const minStart = sorted.reduce((m, c) => Math.min(m, c.baseStart), sorted[0].baseStart)
  const maxEnd = sorted.reduce((m, c) => Math.max(m, c.baseEnd), sorted[0].baseEnd)

  const result = []
  result.push(...baseDoc.slice(region.baseStart, minStart))
  let cursor = minStart
