import { readFileSync } from 'node:fs'
import { computeMergePlan } from './diff3.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function parseInput(text) {
  let lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines = lines.slice(0, -1)
  }
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }
  return parts
}

function main() {
  if (process.argv.length !== 3 || !MODES.has(process.argv[2])) {
    fail('usage: cli.js merge|merge2|regions')
  }
  const mode = process.argv[2]

  const input = readFileSync(0, 'utf8')
  const parts = parseInput(input)
  if (parts.length !== 3) {
    fail('expected three parts separated by %%%')
  }
  const [mine, base, theirs] = parts

  const plan = computeMergePlan(mine, base, theirs)

  let conflict = false
  const out = []

  if (mode === 'regions') {
    for (const part of plan) {
      if (part.kind === 'stable') {
        out.push(`stable ${part.lines.length}`)
      } else if (part.kind === 'conflict') {
        conflict = true
        out.push(`conflict mine=${part.mineLines.length} base=${part.baseLines.length} theirs=${part.theirsLines.length}`)
      } else {
        out.push(`${part.kind} ${part.lines.length}`)
      }
    }
    const text = out.length > 0 ? out.join('\n') + '\n' : ''
    process.stdout.write(text)
    process.exit(conflict ? 1 : 0)
  }

  for (const part of plan) {
    if (part.kind === 'stable' || part.kind === 'mine' || part.kind === 'theirs' || part.kind === 'both') {
      for (const line of part.lines) out.push(line)
    } else if (part.kind === 'conflict') {
      conflict = true
      out.push('<<<<<<< mine')
      for (const line of part.mineLines) out.push(line)
      if (mode === 'merge') {
        out.push('||||||| base')
        for (const line of part.baseLines) out.push(line)
      }
      out.push('=======')
      for (const line of part.theirsLines) out.push(line)
      out.push('>>>>>>> theirs')
    }
  }
  const text = out.length > 0 ? out.join('\n') + '\n' : ''
  process.stdout.write(text)
  process.exit(conflict ? 1 : 0)
}

main()
"}

