 * The scanner. Turns UTF-8 decoded source text into a list of tokens, or
 * throws a LexError describing the first thing that does not scan.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const IDENT_START = /[A-Za-z_]/
const IDENT_PART = /[A-Za-z0-9_]/
const DEC_DIGIT = /[0-9]/
const HEX_DIGIT = /[0-9a-fA-F]/
const BIN_DIGIT = /[01]/
const OCT_DIGIT = /[0-7]/
const TRAILING_NUM_CHAR = /[A-Za-z0-9_]/

const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

export class LexError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

function tabStop(col) {
  return Math.floor((col - 1) / 4) * 4 + 5
}

class Scanner {
  constructor(src) {
    this.chars = Array.from(src)
    this.len = this.chars.length
    this.i = 0
    this.line = 1
    this.col = 1
  }

  eof() {
    return this.i >= this.len
  }

  peek(offset = 0) {
    return this.chars[this.i + offset]
  }

  // Consume the current character and advance position bookkeeping. Returns
  // the character consumed.
  consume() {
    const ch = this.chars[this.i]
    this.i += 1
    if (ch === '\n') {
      this.line += 1
      this.col = 1
    } else if (ch === '\t') {
      this.col = tabStop(this.col)
    } else {
      this.col += 1
    }
    return ch
  }

  fail(line, col, reason) {
    throw new LexError(line, col, reason)
  }
}

function scanDigitRun(sc, isDigit) {
  // Assumes the current run has already had at least one digit consumed.
  // Consumes further digits, and a single underscore only when it sits
  // between two digits of this run.
  for (;;) {
    const c = sc.peek()
    if (c !== undefined && isDigit(c)) {
      sc.consume()
