const OPERATOR_CHARS = new Set(['^', '*', '/', '+', '-', '='])

export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length
  while (i < n) {
    const c = src[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (c >= '0' && c <= '9') {
      let j = i + 1
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      if (j < n && src[j] === '.' && j + 1 < n && src[j + 1] >= '0' && src[j + 1] <= '9') {
        j++
        while (j < n && src[j] >= '0' && src[j] <= '9') j++
      }
      tokens.push({ type: 'NUM', value: parseFloat(src.slice(i, j)) })
      i = j
      continue
    }
    if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')) {
      let j = i + 1
      while (j < n && ((src[j] >= 'A' && src[j] <= 'Z') || (src[j] >= 'a' && src[j] <= 'z'))) j++
      while (j < n && src[j] >= '0' && src[j] <= '9') j++
      tokens.push({ type: 'WORD', text: src.slice(i, j) })
      i = j
      continue
    }
    if (c === '<') {
      if (src[i + 1] === '=') {
        tokens.push({ type: 'OP', op: '<=' })
        i += 2
      } else if (src[i + 1] === '>') {
        tokens.push({ type: 'OP', op: '<>' })
        i += 2
      } else {
        tokens.push({ type: 'OP', op: '<' })
        i += 1
      }
      continue
    }
    if (c === '>') {
      if (src[i + 1] === '=') {
        tokens.push({ type: 'OP', op: '>=' })
        i += 2
      } else {
        tokens.push({ type: 'OP', op: '>' })
        i += 1
      }
      continue
    }
    if (OPERATOR_CHARS.has(c)) {
      tokens.push({ type: 'OP', op: c })
      i += 1
      continue
    }
    if (c === '(') {
      tokens.push({ type: 'LPAREN' })
      i += 1
      continue
    }
    if (c === ')') {
      tokens.push({ type: 'RPAREN' })
      i += 1
      continue
    }
    if (c === ',') {
      tokens.push({ type: 'COMMA' })
      i += 1
      continue
    }
