 * Sheet parsing: turning the raw input text into an ordered list of
 * declared cells (address, content, line number), enforcing the line-level
 * rules and detecting invalid addresses / duplicate declarations.
 */

import { parseAddressStrict, canonAddress } from './address.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
  }
}

// Returns an array of { addr, content, line } in declaration order, or
// throws SheetError with a fully-formed message (without the leading
// "error: ") on the first invalid line.
export function parseSheet(input) {
  let rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  const seen = new Set()
  const cells = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const raw = rawLines[i]
    let start = 0
    while (start < raw.length && (raw[start] === ' ' || raw[start] === '\t')) start++
    const stripped = raw.slice(start)
    if (stripped === '' || stripped[0] === '#') continue

    let idx = 0
    while (idx < stripped.length && stripped[idx] !== ' ' && stripped[idx] !== '\t') idx++
    const addrText = stripped.slice(0, idx)
    let content = ''
    if (idx < stripped.length) {
      let j = idx
      while (j < stripped.length && (stripped[j] === ' ' || stripped[j] === '\t')) j++
      content = stripped.slice(j)
    }

    const parsed = parseAddressStrict(addrText.toUpperCase())
    if (!parsed) {
      throw new SheetError(`line ${lineNo}: invalid cell address ${addrText}`)
    }
    const canon = canonAddress(parsed)
    if (seen.has(canon)) {
      throw new SheetError(`line ${lineNo}: cell ${canon} is declared twice`)
    }
    seen.add(canon)
    cells.push({ addr: canon, col: parsed.col, row: parsed.row, content })
  }

  return cells
}
"}

