 * RFC 3986 generic-syntax parsing, normalization and reference resolution,
 * restricted to the rules this task specifies.
 */

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export class TruncatedPercentError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

function isUnreserved(ch) {
  return (
    (ch >= 'A' && ch <= 'Z') ||
    (ch >= 'a' && ch <= 'z') ||
    (ch >= '0' && ch <= '9') ||
    ch === '-' ||
    ch === '.' ||
    ch === '_' ||
    ch === '~'
  )
}

function lowerAscii(s) {
  let out = ''
  for (const ch of s) {
    out += ch >= 'A' && ch <= 'Z' ? ch.toLowerCase() : ch
  }
  return out
}

/**
 * Split a URI reference into its five generic components. Absent components
 * are `null`; present-but-empty components are `''`. The authority is kept
 * as a single string here; splitAuthority breaks it into userinfo/host/port.
 */
export function parseReference(s) {
  let scheme = null
  let rest = s
  const colonIdx = s.indexOf(':')
  if (colonIdx !== -1) {
    const prefix = s.slice(0, colonIdx)
    if (!/[/?#]/.test(prefix)) {
      scheme = prefix
      rest = s.slice(colonIdx + 1)
    }
  }

  let authority = null
  if (rest.startsWith('//')) {
    let idx = rest.length
    for (let i = 2; i < rest.length; i++) {
      const c = rest[i]
      if (c === '/' || c === '?' || c === '#') {
        idx = i
        break
      }
    }
    authority = rest.slice(2, idx)
    rest = rest.slice(idx)
  }

  let pathEnd = rest.length
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === '?' || c === '#') {
      pathEnd = i
      break
    }
  }
  const path = rest.slice(0, pathEnd)
  rest = rest.slice(pathEnd)

  let query = null
  if (rest.startsWith('?')) {
    let idx = rest.length
    for (let i = 1; i < rest.length; i++) {
      if (rest[i] === '#') {
        idx = i
        break
      }
    }
    query = rest.slice(1, idx)
    rest = rest.slice(idx)
  }

  let fragment = null
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/** Split an authority string into userinfo/host/port, each null when absent. */
export function splitAuthority(authority) {
  let userinfo = null
  let rest = authority
  const atIdx = authority.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = authority.slice(0, atIdx)
    rest = authority.slice(atIdx + 1)
  }
  const bracketIdx = rest.lastIndexOf(']')
  const searchFrom = bracketIdx !== -1 ? bracketIdx : 0
  const colonIdx = rest.indexOf(':', searchFrom)
  let host, port
  if (colonIdx !== -1) {
    host = rest.slice(0, colonIdx)
    port = rest.slice(colonIdx + 1)
  } else {
    host = rest
    port = null
  }
  return { userinfo, host, port }
}

function joinAuthority(userinfo, host, port) {
  let s = ''
  if (userinfo !== null) s += userinfo + '@'
  s += host
  if (port !== null) s += ':' + port
  return s
}

/** Uppercase %XX triplets and decode the ones that are unreserved characters. */
function normalizePercent(str, component) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c === '%') {
      const hex = str.slice(i + 1, i + 3)
      if (hex.length < 2 || !/^[0-9A-Fa-f]{2}$/.test(hex)) {
        throw new TruncatedPercentError(component)
      }
      const upper = hex.toUpperCase()
      const code = parseInt(upper, 16)
      const ch = String.fromCharCode(code)
      out += isUnreserved(ch) ? ch : '%' + upper
      i += 2
    } else {
      out += c
    }
  }
  return out
}

/** Remove dot segments from a path per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '/..') {
      input = '/'
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx
      if (input[0] === '/') {
        idx = input.indexOf('/', 1)
      } else {
        idx = input.indexOf('/')
      }
      if (idx === -1) {
        output += input
        input = ''
      } else {
        output += input.slice(0, idx)
        input = input.slice(idx)
      }
    }
  }
  return output
}

/**
 * Normalize a components object (scheme, authority, path, query, fragment)
 * in place-equivalent fashion, returning a new normalized components object.
 * Throws TruncatedPercentError on a malformed %-encoding.
 */
export function normalizeComponents(c) {
  const scheme = c.scheme !== null ? lowerAscii(c.scheme) : null

  let userinfo = null
  let host = null
  let port = null
  if (c.authority !== null) {
    ;({ userinfo, host, port } = splitAuthority(c.authority))
  }

  const path = normalizePercent(c.path, 'path')
  if (userinfo !== null) userinfo = normalizePercent(userinfo, 'userinfo')
  if (host !== null) host = normalizePercent(host, 'host')
  const query = c.query !== null ? normalizePercent(c.query, 'query') : null
  const fragment = c.fragment !== null ? normalizePercent(c.fragment, 'fragment') : null

  if (host !== null) host = lowerAscii(host)

  if (port !== null) {
    const def = scheme !== null ? DEFAULT_PORTS[scheme] : undefined
    if (port === '' || (def !== undefined && port === def)) {
      port = null
    }
  }

  let finalPath = removeDotSegments(path)

  const authority = c.authority !== null ? joinAuthority(userinfo, host, port) : null

  if (authority !== null && finalPath === '') {
    finalPath = '/'
  }

  return { scheme, authority, path: finalPath, query, fragment }
}

function mergePath(base, refPath) {
  if (base.authority !== null && base.path === '') {
    return '/' + refPath
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) {
    return refPath
  }
  return base.path.slice(0, idx + 1) + refPath
}

/** Resolve a reference against a base per RFC 3986 section 5.2.2, strict mode. */
export function resolveComponents(base, ref) {
  let target
  if (ref.scheme !== null) {
    target = {
      scheme: ref.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
    }
  } else if (ref.authority !== null) {
    target = {
      scheme: base.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
    }
  } else if (ref.path === '') {
    target = {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: ref.query !== null ? ref.query : base.query,
    }
  } else if (ref.path.startsWith('/')) {
    target = {
      scheme: base.scheme,
      authority: base.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
    }
  } else {
    target = {
      scheme: base.scheme,
      authority: base.authority,
      path: removeDotSegments(mergePath(base, ref.path)),
      query: ref.query,
    }
  }
  target.fragment = ref.fragment
  return target
}

/** Serialize a components object back into a URI-reference string. */
export function serialize(c) {
  let s = ''
  if (c.scheme !== null) s += c.scheme + ':'
  if (c.authority !== null) s += '//' + c.authority
  s += c.path
  if (c.query !== null) s += '?' + c.query
  if (c.fragment !== null) s += '#' + c.fragment
  return s
}
"}

