{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parseReference, normalizeComponents, resolveComponents, serialize, TruncatedPercentError } from './uri.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  do {
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead > 0) chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  } while (bytesRead > 0)
  return Buffer.concat(chunks).toString('utf8')
}

function splitRecords(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'normalize' && argv[0] !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }
  const mode = argv[0]

  const input = readStdin()
  const records = splitRecords(input)

  const outLines = []
  for (let i = 0; i < records.length; i++) {
    const lineNo = i + 1
    const record = records[i]
    try {
      if (mode === 'normalize') {
        const parsed = parseReference(record)
        const normalized = normalizeComponents(parsed)
        outLines.push(serialize(normalized))
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) {
          throw { usageMessage: `line ${lineNo}: expected a base and a reference` }
        }
        const baseStr = record.slice(0, spaceIdx)
        const refStr = record.slice(spaceIdx + 1)
        const base = parseReference(baseStr)
        if (base.scheme === null) {
          throw { usageMessage: `line ${lineNo}: the base has no scheme` }
        }
        const ref = parseReference(refStr)
        const target = resolveComponents(base, ref)
        const normalized = normalizeComponents(target)
        outLines.push(serialize(normalized))
      }
    } catch (err) {
      if (err instanceof TruncatedPercentError) {
        fail(`line ${lineNo}: the ${err.component} has a truncated percent-encoding`)
      } else if (err && err.usageMessage) {
        fail(err.usageMessage)
      } else {
        throw err
      }
    }
  }

  process.stdout.write(outLines.map((l) => l + '\n').join(''))
  process.exit(0)
}

main()
"}

