  }

  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      flush(i, j)
      i++
      j++
      runStartBase = i
      runStartSide = j
    } else if (j >= m || (i < n && dp[i + 1][j] >= dp[i][j + 1])) {
      i++
    } else {
      j++
    }
  }
  flush(n, m)

  return changes
