{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { splitLines, splitDocuments } from './parse.js'
import { plan } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytes
    try {
      bytes = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytes === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytes)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.has(args[0])) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }
  const mode = args[0]

  const input = readStdin()
  const lines = splitLines(input)
  let mine, base, theirs
  try {
    ;[mine, base, theirs] = splitDocuments(lines)
  } catch (err) {
    fail(err.message)
    return
  }

  const segments = plan(mine, base, theirs)

  const out = []
  let conflicted = false

  for (const seg of segments) {
    if (seg.kind === 'stable' || seg.kind === 'mine' || seg.kind === 'theirs' || seg.kind === 'both') {
      for (const line of seg.lines) out.push(line)
    } else {
      conflicted = true
      if (mode === 'regions') continue
      out.push('<<<<<<< mine')
      for (const line of seg.mine) out.push(line)
      if (mode === 'merge') {
        out.push('||||||| base')
        for (const line of seg.base) out.push(line)
      }
      out.push('=======')
      for (const line of seg.theirs) out.push(line)
      out.push('>>>>>>> theirs')
    }
  }

  if (mode === 'regions') {
    const regionLines = []
    for (const seg of segments) {
      if (seg.kind === 'conflict') {
        regionLines.push(`conflict mine=${seg.mine.length} base=${seg.base.length} theirs=${seg.theirs.length}`)
      } else {
        regionLines.push(`${seg.kind} ${seg.lines.length}`)
      }
    }
    process.stdout.write(regionLines.map(line => `${line}\n`).join(''))
  } else {
    process.stdout.write(out.map(line => `${line}\n`).join(''))
  }

  process.exit(conflicted ? 1 : 0)
}

main()
"}

