{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e2-harness-vs-product-sonnet-t5-sealed/cell-gUFDIF/src/pack.js","content":"import { computePriorities } from './graph.js'

/**
 * Simulate the build on `workerCount` workers. Returns { log, makespan }
 * where log[i] is the ordered list of { name, start, finish } that worker i
 * ran.
 */
export function packSchedule(tasks, dependencies, workerCount) {
  const priority = computePriorities(tasks, dependencies)
  const names = [...tasks.keys()]

  const freeAt = new Array(workerCount).fill(0)
  const log = Array.from({ length: workerCount }, () => [])
  const finish = new Map()
  const remaining = new Set(names)

  let currentTime = 0
  let makespan = 0

  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let freeWorker = -1
      for (let i = 0; i < workerCount; i++) {
        if (freeAt[i] <= currentTime) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1) break

      let best = null
      for (const name of remaining) {
        const deps = dependencies.get(name) || []
        const ready = deps.every((d) => finish.get(d) <= currentTime)
        if (!ready) continue
        if (
          best === null ||
          priority.get(name) > priority.get(best) ||
          (priority.get(name) === priority.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const start = currentTime
      const f = start + tasks.get(best)
      finish.set(best, f)
      freeAt[freeWorker] = f
      log[freeWorker].push({ name: best, start, finish: f })
      remaining.delete(best)
      if (f > makespan) makespan = f
      progressed = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (freeAt[i] > currentTime && freeAt[i] < next) next = freeAt[i]
    }
    // The graph is acyclic, so some busy worker's finish always unblocks
    // further progress; this should never stay Infinity while work remains.
    currentTime = next
  }

  return { log, makespan }
}
"}

