{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e2-harness-vs-product-sonnet-t5-sealed/cell-gUFDIF/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parser.js'
import { detectCycle, computeSchedule } from './graph.js'
import { packSchedule } from './pack.js'

const WORKERS_RE = /^[1-9][0-9]*$/

function usageError() {
  return new CliError('usage: cli.js waves|explain|pack <workers>')
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw usageError()
}

function runWaves(tasks, dependencies) {
  const schedule = computeSchedule(tasks, dependencies)
  const names = [...tasks.keys()].sort()

  let maxDepth = -1
  let total = 0
  for (const name of names) {
    const info = schedule.get(name)
    if (info.depth > maxDepth) maxDepth = info.depth
    if (info.finish > total) total = info.finish
  }

  const lines = []
  for (let depth = 0; depth <= maxDepth; depth++) {
    const inWave = names.filter((n) => schedule.get(n).depth === depth)
    lines.push(`wave ${depth}: ${inWave.join(' ')}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function runExplain(tasks, dependencies) {
  const schedule = computeSchedule(tasks, dependencies)
  const names = [...tasks.keys()].sort()

  let total = 0
  const lines = []
  for (const name of names) {
    const info = schedule.get(name)
    if (info.finish > total) total = info.finish
    lines.push(`${name} start=${info.start} finish=${info.finish} depth=${info.depth}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function runPack(tasks, dependencies, workers) {
  const { log, makespan } = packSchedule(tasks, dependencies, workers)
  const lines = []
  for (let i = 0; i < workers; i++) {
    const parts = log[i].map((t) => ` ${t.name}@${t.start}-${t.finish}`)
    lines.push(`worker ${i}:${parts.join('')}`)
  }
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  let parsedArgs
  try {
    parsedArgs = parseArgs(process.argv.slice(2))
  } catch (err) {
    if (err instanceof CliError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(err.exitCode)
    }
    throw err
  }

  const input = readFileSync(0, 'utf8')

  let tasks
  let dependencies
  try {
    ;({ tasks, dependencies } = parseGraph(input))
    detectCycle(tasks, dependencies)
  } catch (err) {
    if (err instanceof CliError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(err.exitCode)
    }
    throw err
  }

  let output
  if (parsedArgs.mode === 'waves') {
    output = runWaves(tasks, dependencies)
  } else if (parsedArgs.mode === 'explain') {
    output = runExplain(tasks, dependencies)
  } else {
    output = runPack(tasks, dependencies, parsedArgs.workers)
  }

  process.stdout.write(output)
}

main()
"}

