 * Per-key state machines for the two policy kinds. Each keeps one
 * independent state per key, created lazily on first use.
 */

export class TokenBucketPolicy {
  constructor(spec) {
    this.capacity = spec.capacity // BigInt
    this.refill = spec.refill // BigInt
    this.per = spec.per // BigInt
    this.states = new Map() // key -> { scaled: BigInt, lastTick: BigInt }
  }

  _stateFor(key) {
    let s = this.states.get(key)
    if (s === undefined) {
      s = { scaled: this.capacity * this.per, lastTick: null }
      this.states.set(key, s)
    }
    return s
  }

  advance(key, tick) {
    const s = this._stateFor(key)
    if (s.lastTick === null) {
      s.lastTick = tick
      return
    }
    const elapsed = tick - s.lastTick
    if (elapsed > 0n) {
      s.scaled += this.refill * elapsed
      const capScaled = this.capacity * this.per
      if (s.scaled > capScaled) {
        s.scaled = capScaled
      }
      s.lastTick = tick
    }
  }

  allows(key) {
    const s = this._stateFor(key)
    return s.scaled >= this.per
  }

  record(key) {
    const s = this._stateFor(key)
    s.scaled -= this.per
  }
}

export class SlidingWindowPolicy {
  constructor(spec) {
    this.limit = spec.limit // BigInt
    this.span = spec.span // BigInt
    this.states = new Map() // key -> array of ticks (BigInt), ascending
  }

  _stateFor(key) {
    let s = this.states.get(key)
    if (s === undefined) {
      s = []
      this.states.set(key, s)
    }
    return s
  }

  advance(key, tick) {
    const s = this._stateFor(key)
    const threshold = tick - this.span
    let cut = 0
    while (cut < s.length && s[cut] <= threshold) {
      cut++
    }
    if (cut > 0) {
      s.splice(0, cut)
    }
  }

  allows(key) {
    const s = this._stateFor(key)
    return BigInt(s.length) < this.limit
  }

  record(key, tick) {
    const s = this._stateFor(key)
    s.push(tick)
  }
}

export function makePolicy(spec) {
  if (spec.kind === 'bucket') {
    return new TokenBucketPolicy(spec)
  }
  return new SlidingWindowPolicy(spec)
}
"}

