function readStdin() {
  const chunks = []
  const fs = require_fs()
  const fd = 0
  const buf = Buffer.alloc(65536)
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') {
        continue
      }
      if (err.code === 'EOF') {
        break
      }
      throw err
    }
    if (bytesRead === 0) {
      break
    }
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

