  // Lazily required to keep the top of the file focused on the program's
  // own modules.
  return globalThis.__fsModule
}

async function main() {
  const { readFileSync } = await import('node:fs')
  globalThis.__fsModule = { readSync: (await import('node:fs')).readSync }

