  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    throw new UsageError('usage: cli.js replay|summary')
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')

  const parsed = parse(input)
  const verdicts = simulate(parsed)
  const output = mode === 'replay' ? formatReplay(verdicts) : formatSummary(verdicts)
  process.stdout.write(output)
}

