{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e2-harness-vs-product-sonnet-t5-sealed/cell-ia0UR6/src/parse.js","content":"/**
 * Parses election input text into a declared candidate list and a list of
 * ballots, or throws a ParseError describing the first problem found.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidatesDeclared = false
  const candidateSet = new Set()
  const candidateOrder = []
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidatesDeclared) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNo)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ParseError('expected candidates <name>...', lineNo)
      }
      const seen = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(`invalid candidate name ${name}`, lineNo)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is declared twice`, lineNo)
        }
        seen.add(name)
      }
      for (const name of names) {
        candidateSet.add(name)
        candidateOrder.push(name)
      }
      candidatesDeclared = true
    } else if (word === 'ballot') {
      if (!candidatesDeclared) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNo)
      }
      if (tokens.length < 3) {
        throw new ParseError('expected ballot <count> <candidate>...', lineNo)
      }
      const countStr = tokens[1]
      if (!COUNT_RE.test(countStr)) {
        throw new ParseError('count must be a positive integer', lineNo)
      }
      const count = Number(countStr)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(`unknown candidate ${name}`, lineNo)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is repeated`, lineNo)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw new ParseError(`unknown directive ${word}`, lineNo)
    }
  }

  if (!candidatesDeclared) {
    throw new ParseError('no candidates', null)
  }

  return { candidates: candidateOrder, ballots }
}
"}

