 */

import { readFileSync } from 'node:fs'
import { parseElection, ParseError } from './parse.js'
import { runElection } from './count.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }
  const mode = args[0]

  let input
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let election
  try {
    election = parseElection(input)
  } catch (e) {
    if (e instanceof ParseError) {
      const prefix = e.line === null ? '' : `line ${e.line}: `
      fail(`${prefix}${e.message}`)
      return
    }
    throw e
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)

  const out = []
  if (mode === 'rounds') {
    for (const r of rounds) {
      const entries = r.entries.map((e) => `${e.name}=${e.votes}`).join(' ')
      out.push(`round ${r.number}: ${entries} exhausted=${r.exhausted}`)
      if (r.eliminated !== null) {
        out.push(`eliminated ${r.eliminated}`)
      }
    }
  } else {
    out.push(`rounds ${rounds.length}`)
  }
  out.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(out.join('\n') + '\n')
}

main()
"}

