{"file_path":"src/format.js","content":"function cmpCodePoint(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

function jsonValue(node, indent) {
  switch (node.kind) {
    case 'table': {
      const keys = [...node.map.keys()].sort(cmpCodePoint)
      if (keys.length === 0) return '{}'
      const inner = keys
        .map((k) => `${indent}  ${JSON.stringify(k)}: ${jsonValue(node.map.get(k), indent + '  ')}`)
        .join(',\n')
      return `{\n${inner}\n${indent}}`
    }
    case 'array':
    case 'array-of-tables': {
      const items = node.items
      if (items.length === 0) return '[]'
      const inner = items.map((it) => `${indent}  ${jsonValue(it, indent + '  ')}`).join(',\n')
      return `[\n${inner}\n${indent}]`
    }
    case 'string':
    case 'integer':
    case 'float':
    case 'boolean':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJson(root) {
  return jsonValue(root, '') + '\n'
}

function typeName(node) {
  switch (node.kind) {
    case 'table':
      return 'table'
    case 'array':
    case 'array-of-tables':
      return 'array'
    case 'string':
      return 'string'
    case 'integer':
      return 'integer'
    case 'float':
      return 'float'
    case 'boolean':
      return 'boolean'
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

function walk(node, path, out) {
  if (path !== null) out.push(`${path} ${typeName(node)}`)
  if (node.kind === 'table') {
    const keys = [...node.map.keys()].sort(cmpCodePoint)
    for (const k of keys) {
      const childPath = path !== null ? `${path}.${k}` : k
      walk(node.map.get(k), childPath, out)
    }
  } else if (node.kind === 'array' || node.kind === 'array-of-tables') {
    node.items.forEach((it, i) => {
      const childPath = `${path}[${i}]`
      walk(it, childPath, out)
    })
  }
}

export function toKeys(root) {
  const out = []
  walk(root, null, out)
  return out.map((l) => l + '\n').join('')
}
"}

